def find_path(graph, start, goal):
    # Track the path from start to goal
    path = []
    # Track visited nodes
    visited = set()

    def search(node):
        if node == goal:
            path.append(goal)
            path.append(start)
            return True
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if search(neighbor):
                path.append(node)
                return True
        return False

    if search(start):
        return path[::-1]
    return None
