```python
def find_path(graph, start, goal):
    def custom_path_search(current_node, path, visited):
        visited.add(current_node)
        if current_node == goal:
            return path + [goal]

        for neighbor in graph.get(current_node, []):
            if neighbor not in visited:
                result = custom_path_search(neighbor, path + [current_node], visited)
                if result is not None:
                    return result
        return None

    visited = set()
    return custom_path_search(start, [start], visited)

# Example usage:
graph = {
    'A': ['B', 'C'],
    'B': ['D', 'E'],
