def find_path(graph, start, goal):
    # Initialize an empty dictionary to keep track of visited nodes
    visited = {}
    # Initialize a queue for BFS
    queue = [(start, [start])]

    # Perform BFS
    while queue:
        (node, path) = queue.pop(0)
        if node not in visited:
            visited[node] = path
            if node == goal:
                return path
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))

    # If goal is unreachable, return None
    return None

