def find_path(graph, start, goal):
    # Initialize the stack for DFS and a set to keep track of visited nodes
    stack = [(start, [start])]

    while stack:
        (node, path) = stack.pop()

        if node in graph:
            for neighbor in graph[node]:
                if neighbor not in path:
                    # If the neighbor is the goal node, return the path
                    if neighbor == goal:
                        return path + [neighbor]
                    else:
                        stack.append((neighbor, path + [neighbor]))

