def find_path(graph, start, goal):
    if start == goal:
        return [start]

    # Initialize the queue with the start node and an empty list to store the path
    queue = [(start, [start])]

    while queue:
        (current_node, path) = queue.pop(0)

        for neighbor in graph[current_node]:
