    def dfs(node, path, visited):
        # If we found the goal, return the current path
        if node == goal:
            return path + [goal]

        # Mark the current node as visited
        visited.add(node)

        # Recursively search for the goal in all unvisited neighboring nodes
        for neighbor in graph.get(node, []):
