from collections import deque

def shortest_path(graph, source, target):
    # Initialize distances and previous nodes
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {}

    # Priority queue for BFS, storing (distance, node) tuples
    queue = deque([(0, source)])

    while queue:
        current_distance, current_node = queue.popleft()

        # If we reached the target, reconstruct the path
        if current_node == target:
            path[target] = []
            while current_node in path:
                path[target].insert(0, current_node)
                current_node = path[current_node][0]
            path[target].insert(0, source)
            return (current_distance, path[target])

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                queue.append((distance, neighbor))
                path[neighbor] = path[current_node] + [neighbor]

    # If no path is found, the target is unreachable
    return (float('inf'), None)

# Example usage:
