def shortest_path(graph, source, target):
    # Initialize the distance dictionary with infinity for all nodes except source
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the visited dictionary to keep track of visited nodes
    visited = {}

    # Create a priority queue to process nodes
    priority_queue = [(0, source)]

    while priority_queue:
        # Get the node with the smallest distance
        current_distance, current_node = heapq.heappop(priority_queue)

        # If this node has already been visited, skip it
        if current_node in visited:
            continue

        visited[current_node] = current_distance

        # Check all neighbors of the current node
        for neighbor, weight in graph.get(current_node, []):
            distance = distances[current_node] + weight

            # Check if this is a shorter path to the neighbor
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                # Add the neighbor to the priority queue
                heapq.heappush(priority_queue, (distance, neighbor))

    # Check if the target node has been visited
