def shortest_path(graph, source, target):
    # Initialize the distance matrix with the graph's edge weights
    # If there is no direct edge, the distance is set to infinity
    distance_matrix = {node: {neighbor: weight if (node, neighbor) in graph[node] else float("inf") 
                              for neighbor, weight in graph[node]}
                       for node in graph}

    # Initialize the path matrix with each node pointing to itself
    path_matrix = {node: [node] for node in graph}

    # Floyd-Warshall algorithm to find shortest paths between all pairs of nodes
    for k in graph:
        for i in graph:
            for j in graph:
