def shortest_path(graph, source, target):
    import heapq

    def dijkstra(graph, start):
        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

    def add_self_loops(graph):
        for node in graph:
            graph[node].append((node, 0))  # Adding self-loop with weight 0

    def clear_inf(graph):
        for node in graph:
            if len(graph[node]) > 0 and graph[node][0][1] == float('inf'):
                graph[node].remove((node, 0))
            for i in range(len(graph[node])):
                if graph[node][i][1] == float('inf'):
                    graph[node].pop(i)
                    i -= 1

    # Step 1: Count number of nodes in the graph
    n = len(graph)

    # Step 2: Apply Johnson's algorithm
    # 1. Add a new node to the graph to handle self-loops
    add_self_loops(graph)

    # 2. For each node, add a new edge to the graph with weight 0
    # to handle the new node
    for node in graph:
        graph[node].append((n, 0))

    # 3. Run single-source shortest path algorithm (Dijkstra) from the new node to all other nodes
    new_distances = dijkstra(graph, n)

    # Step 3: Clear the inf values from the graph
    clear_inf(graph)

    # Step 4: Remove the new node and edges
    graph.pop(n)
    for node in graph:
        for i in range(len(graph[node])):
            if len(graph[node]) > 0 and graph[node][i][0] == n:
                graph[node].remove(graph[node][i])
                break

    # Step 5: Run single-source shortest path algorithm (Dijkstra) again from the original source to the target
    distances = dijkstra(graph, source)

    # Get the shortest path distance and the path itself
    shortest_distance = distances[target] if target in distances else float('inf')
